// Seconds until ClaimVoiceTranscriptRecovery can take the Capture's recovery;
// Infinity when it cannot: a failed recovery waits for a manual retry.
func (q *Queries) VoiceTranscriptRecoveryDueIn(ctx context.Context, id string) (float64, error) {
	row := q.db.QueryRow(ctx, voiceTranscriptRecoveryDueIn, id)
	var wait_seconds float64
	err := row.Scan(&wait_seconds)
	return wait_seconds, err
}
